process.commandLine:
hp=${HTTP_PROXY#http://}
hp=${hp%/}
echo PROXY_ENV=$HTTP_PROXY
echo VIA_PROXY=$(printf 'GET http://example.com/ HTTP/1.0\r\n\r\n' | nc -w 10 "${hp%:*}" "${hp##*:}" | head -n1 | cut -d' ' -f2)
nslookup host.wslc.internal >/dev/null 2>&1 && echo HOST_DNS=RESOLVED || echo HOST_DNS=REFUSED
nc -z -w 3 1.1.1.1 443 && echo DIRECT=REACHED || echo DIRECT=BLOCKED
